const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  function evaluate(obj) {
    return new Promise((resolve, reject) => obj.evaluate(resolve, reject));
  }

  try {
    // 1. Geometry & Time Definitions
    const start = ee.Date('2009-08-03');
    const end = ee.Date('2009-08-10'); // exclusive
    const startStr = '2009-08-03';
    const endStr = '2009-08-09';
    // Taiwan geometry (primary: LSIB, fallback: GAUL, last resort: rectangle)
    let taiwanFC = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
      .filter(ee.Filter.eq('country_na', 'Taiwan'));
    let fcSize = await evaluate(taiwanFC.size());
    let geomSource = 'LSIB_SIMPLE/2017';
    if (!fcSize || fcSize === 0) {
      taiwanFC = ee.FeatureCollection('FAO/GAUL/2015/level0')
        .filter(ee.Filter.eq('ADM0_NAME', 'Taiwan, Province of China'));
      fcSize = await evaluate(taiwanFC.size());
      geomSource = 'FAO/GAUL/2015';
    }
    let taiwanGeom;
    if (fcSize && fcSize > 0) {
      taiwanGeom = taiwanFC.geometry();
    } else {
      // Last resort rectangle around Taiwan
      taiwanGeom = ee.Geometry.Rectangle([119.0, 21.5, 122.2, 25.5], null, false);
      geomSource = 'FallbackRect';
    }

    // Split into North/South by latitude 23.5N
    const northWorld = ee.Geometry.Rectangle([-180, 23.5, 180, 90], null, false);
    const southWorld = ee.Geometry.Rectangle([-180, -90, 180, 23.5], null, false);
    const northGeom = taiwanGeom.intersection(northWorld, ee.ErrorMargin(1000));
    const southGeom = taiwanGeom.intersection(southWorld, ee.ErrorMargin(1000));

    // 2. Data Acquisition & Check with fallback
    const chirpsCol0 = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, end)
      .filterBounds(taiwanGeom)
      .select(['precipitation']);
    let col = chirpsCol0;
    let dataset = 'CHIRPS_DAILY';
    let scale = 6000;
    let imgCount = await evaluate(col.size());

    if (!imgCount || imgCount === 0) {
      // Fallback to TRMM 3B42 3-hourly
      let trmm = ee.ImageCollection('TRMM/3B42')
        .filterDate(start, end)
        .filterBounds(taiwanGeom)
        .select(['precipitation']);
      let trmmCount = await evaluate(trmm.size());
      if (trmmCount && trmmCount > 0) {
        col = trmm;
        dataset = 'TRMM_3B42_3hourly';
        scale = 25000;
        imgCount = trmmCount;
      } else {
        // Widen date window for CHIRPS as a recovery
        const wStart = ee.Date('2009-08-01');
        const wEnd = ee.Date('2009-08-12');
        const chirpsWide = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
          .filterDate(wStart, wEnd)
          .filterBounds(taiwanGeom)
          .select(['precipitation']);
        const chirpsWideCount = await evaluate(chirpsWide.size());
        if (chirpsWideCount && chirpsWideCount > 0) {
          col = chirpsWide;
          dataset = 'CHIRPS_DAILY_WIDE';
          scale = 6000;
          imgCount = chirpsWideCount;
        } else {
          console.log(`Geom: ${geomSource}`);
          console.log(`Primary period ${startStr} to ${endStr}: 0 images`);
          console.log('Recovery failed: no data in wider window.');
          console.log('C1');
          return;
        }
      }
    }

    // 3. Processing
    let sumImage;
    if (dataset.startsWith('CHIRPS')) {
      // mm/day summed to total mm
      sumImage = col.sum().rename('p');
    } else {
      // TRMM 3-hourly: mm/hr * 3h => mm; sum to total mm
      const mmCol = col.map(img => img.multiply(3).rename('p').copyProperties(img, img.propertyNames()));
      sumImage = mmCol.sum().rename('p');
    }

    const reducers = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const statsN = ee.Dictionary(sumImage.reduceRegion({
      reducer: reducers,
      geometry: northGeom,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    const statsS = ee.Dictionary(sumImage.reduceRegion({
      reducer: reducers,
      geometry: southGeom,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));

    const nMean = await evaluate(statsN.get('p_mean'));
    const sMean = await evaluate(statsS.get('p_mean'));
    const nCount = await evaluate(statsN.get('p_count'));
    const sCount = await evaluate(statsS.get('p_count'));

    // 4. Validation & Final Answer
    console.log(`Geom: ${geomSource}`);
    console.log(`Dataset: ${dataset}, Images: ${imgCount}, Period: ${startStr} to ${endStr}`);
    console.log(`North pixels: ${nCount}, South pixels: ${sCount}`);

    if (!nCount || !sCount || nCount === 0 || sCount === 0) {
      console.log('No valid pixels after processing.');
      console.log('C2');
      return;
    }

    // Check calculation validity
    const invalid = (v) => v === null || v === undefined || !isFinite(v) || v < 0 || v > 10000;
    if (invalid(nMean) || invalid(sMean)) {
      console.log(`North mean mm: ${nMean}, South mean mm: ${sMean}`);
      console.log('C3');
      return;
    }

    const diff = sMean - nMean;
    console.log(`North mean total rainfall (mm): ${nMean.toFixed(2)}`);
    console.log(`South mean total rainfall (mm): ${sMean.toFixed(2)}`);
    console.log(`Difference (South - North) mm: ${diff.toFixed(2)}`);

    if (sMean > nMean) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    // Likely dataset/band/method error or memory issue
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
